'use strict';
(function(){
 const main=document.querySelector('#main'),status=document.querySelector('#connection'),Store=SproutStoryStore;
 let catalog,legacy,documentState,theme=1,selected=new Set(),busy=false,audioGeneration=0,calendarMonth=null,calendarDate=null;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const uid=()=>crypto.randomUUID(),S=()=>documentState.storyV1,D=()=>S().draft;
 const pack=id=>catalog.packages.find(p=>p.id===Number(id));
 const $=s=>document.querySelector(s), all=s=>[...document.querySelectorAll(s)];
 function message(text,error=false){status.textContent=text;status.className=error?'error':'';}
 function cancel(){audioGeneration++;SproutSpeech.cancel();}
 function nav(route){cancel();location.hash=route;render();window.scrollTo(0,0);}
 async function save(action,paint=true){if(busy)return false;busy=true;all('button').forEach(b=>b.disabled=true);
  try{documentState=await Store.transaction({...action,expectedRevision:S().revision,eventId:action.eventId||uid()},catalog,legacy);message('已保存到当前浏览器');return true;}
  catch(e){message(e.message+'。请重试，先不要清除浏览器数据。',true);return false;}
  finally{busy=false;if(paint)render();for(const id of ['#home-link','#calendar-link','#plan-link']){const b=$(id);if(b)b.disabled=false;}}
 }
 function speak(text,onEnd){cancel();const token=audioGeneration;const note=$('#audio-note');if(note)note.textContent='正在播放，可暂停或再听一遍。';
  SproutSpeech.speak(text,{start:()=>{if(note)note.textContent='晓晓正在读…';},end:async()=>{if(token!==audioGeneration)return;if(note)note.textContent='听完了。';if(onEnd)await onEnd();},error:reason=>{if(token!==audioGeneration)return;if(note)note.textContent=reason+' 请点播放重试。';}});
 }
 function bind(id,fn){const e=$(id);if(e)e.onclick=fn;}
 function art(id){return SproutStoryArt.scene(id);}
 function step(n,text){return `<div class="step-label">${n} / 6 · ${text}</div>`;}
 function audioBar(label='听一听'){return `<div class="actions"><button id="play" class="primary">▶ ${label}</button><button id="stop">暂停</button></div><p id="audio-note" role="status">点播放听晓晓普通话。只有完整播放才记录听过。</p>`;}
 function render(){if(!catalog||!documentState)return;
  const [view='home',id]=location.hash.slice(1).split('/');
  if(view==='preview'&&pack(id))preview(pack(id));else if(view==='pick'&&pack(id))pick(pack(id));else if(view==='learn'&&D())activity();else if(view==='calendar')calendar();else if(view==='plan')roadmap();else if(view==='reread')reread(id);else home();
  bind('#home-link',()=>nav('home'));bind('#calendar-link',()=>nav('calendar'));bind('#plan-link',()=>nav('plan'));
 }
 function home(){
  const group=catalog.themes.find(t=>t.id===theme),items=catalog.packages.filter(p=>p.theme===group.title);
  main.innerHTML=`${step(1,'自由选故事')}<section class="story-hero"><div><p class="eyebrow">第一阶段 · 在有趣的故事里认识字</p><h1>今天想听哪个故事？</h1><p>每一个都能直接进入。一次挑几个字，累了就歇一歇。</p>${D()&&D().phase!=='summary'?'<button class="primary" id="resume">接着上次的故事</button>':''}</div><div class="hero-art">${art(items[0].id)}</div></section><p class="note">${recordingsReady()?'':'录音待补齐 · 当前为测试版本。'}53 个故事包 · 13 个主题 · 133 句复读。5 字是一包的候选量，不是每日任务。听过、练过，都不等于掌握。</p><nav class="themes" aria-label="主题">${catalog.themes.map(t=>`<button data-theme="${t.id}" aria-pressed="${theme===t.id}">${esc(t.title)}</button>`).join('')}</nav><h2>${esc(group.title)}</h2><section class="story-grid">${items.map(p=>`<article class="story-card"><div class="card-art">${art(p.id)}</div><small>故事 ${String(p.id).padStart(2,'0')}</small><h3>${esc(p.title)}</h3><p class="candidates">${p.characters.join('　')}</p><div class="actions"><button data-preview="${p.id}">先看内容</button><button data-pick="${p.id}" class="primary">听这个故事</button></div></article>`).join('')}</section><section class="soft-panel"><h2>这个主题，再读一读</h2><p>逐句确认实际已知字；有不认识的字就一起听，不登记为独立阅读。</p><button id="reread">打开主题复读</button></section><section class="soft-panel"><h2>基础 35 字与以前的记录</h2><p>基础字是家长报告，仍需逐字观察。旧课程和原有日历完整保留。</p><p class="foundation">${catalog.foundation.join(' ')}</p><a class="button" href="/legacy.html#home/sprout-2">打开原课程与原记录</a></section>`;
  all('[data-theme]').forEach(b=>b.onclick=()=>{theme=+b.dataset.theme;cancel();render();});all('[data-preview]').forEach(b=>b.onclick=()=>nav('preview/'+b.dataset.preview));all('[data-pick]').forEach(b=>b.onclick=()=>{selected=new Set(pack(b.dataset.pick).characters.filter(ch=>!S().known[ch]));nav('pick/'+b.dataset.pick);});bind('#resume',()=>nav('learn'));bind('#reread',()=>nav('reread/T'+String(theme).padStart(2,'0')));
 }
 function preview(p){main.innerHTML=`${step(1,'先看内容')}<h1>${esc(p.title)}</h1><div class="wide-art">${art(p.id)}</div><p class="candidates">候选字：${p.characters.join('　')}</p><div class="reading">${p.sentences.map(t=>`<p>${esc(t)}</p>`).join('')}</div><p class="note">预览不生成学习记录。故事中不认识的支持字都可以听，不假设已经学过前面的课。</p><details><summary>给大人：场景玩法与读音提醒</summary><p>${esc(p.adultNote).replaceAll('\n','<br>')}</p></details><div class="actions"><button id="back">返回故事</button><button id="choose" class="primary">挑几个字玩</button></div>`;bind('#back',()=>nav('home'));bind('#choose',()=>{selected=new Set(p.characters.filter(ch=>!S().known[ch]));nav('pick/'+p.id);});}
 function pick(p){main.innerHTML=`${step(2,'挑几个字玩')}<h1>${esc(p.title)}</h1><p class="lead">想玩哪些字？点一下选择或跳过。</p><p class="note">“家长说已会”只是跳过建议，不等于本次验证。可以选 0–5 个字。</p><div class="choose-characters">${p.characters.map(ch=>`<div><button class="character-choice" data-char="${ch}" aria-pressed="${selected.has(ch)}">${ch}<small>${selected.has(ch)?'这次玩':'先跳过'}</small></button><label><input type="checkbox" data-known="${ch}" ${S().known[ch]?'checked':''}> 家长说已会</label></div>`).join('')}</div><p class="selection-count">本次 ${selected.size} 个字${selected.size===0?' · 也可以只听故事':''}</p><div class="actions"><button id="all">全选</button><button id="none">全不选</button><button class="primary" id="begin">开始听故事</button><button id="listen-only">只听故事</button></div><button id="back">返回预览</button>`;
  all('[data-char]').forEach(b=>b.onclick=()=>{selected.has(b.dataset.char)?selected.delete(b.dataset.char):selected.add(b.dataset.char);render();});all('[data-known]').forEach(b=>b.onchange=async()=>{if(b.checked)selected.delete(b.dataset.known);await save({type:'known',char:b.dataset.known,value:b.checked});});bind('#all',()=>{selected=new Set(p.characters);render();});bind('#none',()=>{selected.clear();render();});bind('#back',()=>nav('preview/'+p.id));
  const begin=async chars=>{cancel();if(await save({type:'start',packageId:p.id,selected:chars,sessionId:uid()}))nav('learn');};bind('#begin',()=>begin([...selected]));bind('#listen-only',()=>begin([]));
 }
 function activity(){const d=D(),p=pack(d.packageId);if(d.phase==='story')story(d,p);else if(d.phase==='meaning')meaning(d,p);else if(d.phase==='recognize')recognize(d,p);else summary(d,p);}
 function exit(){cancel();nav('home');}
 async function finish(listenOnly){cancel();await save({type:'finish',sessionId:D().id,listenOnly});}
 function story(d,p){const index=d.sentenceIndex,text=p.sentences[index];main.innerHTML=`${step(3,'听图共读')}<div class="section-head"><h1>${esc(p.title)}</h1><button id="exit">先休息</button></div><div class="wide-art">${art(p.id)}</div><p class="sentence">${esc(text)}</p><p>第 ${index+1} / ${p.sentences.length} 句 ${d.heard.includes(text)?'· 已完整听过':''}</p>${audioBar(d.heard.includes(text)?'再听一遍':'听故事')}<div class="actions"><button id="prev" ${index===0?'disabled':''}>上一句</button><button id="next" ${index===p.sentences.length-1?'disabled':''}>下一句</button><button id="meaning" class="primary" ${d.heard.length!==p.sentences.length?'disabled':''}>看图理解</button></div><p class="note">不认识的字也能一起听。画面帮助理解故事，不作为认字结果。</p><button id="only" ${!d.heard.length?'disabled':''}>今天只记听过</button>`;
  bind('#exit',exit);bind('#play',()=>speak(text,()=>save({type:'heard',sessionId:d.id,text})));bind('#stop',()=>{cancel();$('#audio-note').textContent='已暂停。本句尚未播完时不会记听过；再点播放从头听。';});for(const [id,i] of [['#prev',index-1],['#next',index+1]])bind(id,async()=>{cancel();await save({type:'sentence',sessionId:d.id,index:i});});bind('#meaning',async()=>{cancel();await save({type:'phase',sessionId:d.id,phase:'meaning'});});bind('#only',()=>finish(true));
 }
 function meaning(d,p){const question=SproutStoryArt.question(p.id),options=SproutStoryArt.choices(p.id);main.innerHTML=`${step(4,'看图理解')}<h1>${esc(question)}</h1><p class="note">这是理解题，可以听题、看图。答对不登记为识字掌握。</p>${audioBar('再听题目')}<section class="picture-options">${options.map(o=>`<button class="picture-option" data-choice="${esc(o.key)}" aria-label="${esc(o.label)}">${o.svg}</button>`).join('')}</section><div class="meaning-feedback" role="status">${d.meaning?(d.meaning.correct?'你找到这幅图了！':'再看看故事里的意思，也可以请大人讲一讲。'):''}</div><div class="actions"><button id="story-again">回故事再听</button><button id="recognize" class="primary" ${!d.meaning?'disabled':''}>换句试读</button><button id="only">没有大人陪同，只记听过</button><button id="exit">先休息</button></div>`;
  bind('#play',()=>speak(question));bind('#stop',cancel);bind('#exit',exit);all('[data-choice]').forEach(b=>b.onclick=async()=>{cancel();await save({type:'meaning',sessionId:d.id,answer:b.dataset.choice,correct:b.dataset.choice===SproutStoryArt.answer(p.id)});});bind('#story-again',async()=>{cancel();await save({type:'backToStory',sessionId:d.id});});bind('#recognize',async()=>{cancel();if(d.selected.length)await save({type:'phase',sessionId:d.id,phase:'recognize'});else await finish(true);});bind('#only',()=>finish(true));
 }
 function recognize(d,p){const target=p.recognition.find(x=>d.selected.includes(x.char)&&!d.checks.some(o=>o.char===x.char));if(!target){main.innerHTML=`${step(5,'观察已记录')}<h1>这一轮试读结束啦</h1><p>本次表现已逐字保存，学完不等于掌握。</p><button class="primary" id="finish">留下今天的记录</button>`;bind('#finish',()=>finish(false));return;}
  const helped=Boolean(d.helped[target.char]);const sentence=esc(target.sentence).split(target.char).join(`<mark>${target.char}</mark>`);main.innerHTML=`${step(5,d.reviewPlan?'按真实日期回访':'换句试读')}<h1>框里的字认识吗？</h1><p>请大人听孩子先试读，再据实记录。只观察框里的字，不要求整句都会。</p><div class="recognition-sentence">${sentence}</div><p class="note">${helped?'本字已得到帮助，不能再记独立读出。':'这里没有图、拼音或自动朗读。未知的支持字若需要带读，先点“需要帮助”。'}</p><div class="observation-actions"><button id="independent" class="success" ${helped?'disabled':''}>✓ 独立读出</button><button id="prompted" class="warm">提示后读出</button><button id="uncertain">还不确定</button></div><div class="actions"><button id="answer">听听答案（记帮助）</button><button id="help">需要帮助（记帮助）</button><button id="stop">暂停声音</button></div><p id="audio-note" role="status">听答案会把该句说出的本轮待观察字都记为得到帮助，只能选择“提示后读出”或“还不确定”。</p><div class="actions"><button id="only">跳过剩余试读</button><button id="exit">先休息</button></div>`;
  bind('#exit',exit);bind('#stop',cancel);for(const result of ['independent','prompted','uncertain'])bind('#'+result,async()=>{cancel();await save({type:'observe',sessionId:d.id,char:target.char,status:result});});bind('#help',async()=>{cancel();await save({type:'help',sessionId:d.id,char:target.char});});
  bind('#answer',async()=>{if(busy)return;cancel();if(await save({type:'help',sessionId:d.id,char:target.char,answerAudio:true}))speak(target.sentence);else message('帮助记录保存失败，未播放答案；请恢复存储后重试。',true);});bind('#only',()=>finish(true));
 }
 function summary(d,p){const labels={independent:'本次独立读出',prompted:'提示后读出',uncertain:'还不确定'};main.innerHTML=`${step(6,'留下真实记录')}<section class="summary-card"><h1>每一次尝试，都值得看见</h1><h2>${esc(p.title)}</h2><p>${esc(d.finishedDate)} · ${d.heard.length?'听过 '+d.heard.length+' 句故事':'回访观察'}</p><ul class="results">${d.checks.map(x=>`<li><strong>${x.char}</strong><span>${labels[x.status]}</span></li>`).join('')||'<li>这次只听故事，没有新增认字验证。</li>'}</ul><p>本次记录不是掌握结论。家长报告已会与本次观察分别保存。</p><div class="actions"><button class="primary" id="done">今天结束</button><button id="another">换个故事</button><button id="records">看实际日期和回访</button></div></section>`;bind('#done',()=>nav('home'));bind('#another',()=>nav('home'));bind('#records',()=>nav('calendar'));}
 function reread(id){const r=catalog.rereads.find(r=>r.id===id)||catalog.rereads[0];main.innerHTML=`<p class="eyebrow">主题复读 · ${esc(r.theme)}</p><h1>${esc(r.title)}</h1><p class="note">逐句确认孩子实际已知字。有未知字就共读；这里仅记录听过，不自动登记独立阅读或掌握。</p><div id="audio-note" role="status"></div><button id="stop">暂停声音</button><div class="reread-lines">${r.sentences.map((text,i)=>`<article><p>${esc(text)}</p><button data-line="${i}">▶ 听这一句</button></article>`).join('')}</div><p>${esc(r.note)}</p><button id="back">返回故事</button>`;all('[data-line]').forEach(b=>b.onclick=()=>{const text=r.sentences[+b.dataset.line];speak(text,()=>save({type:'reread',groupId:r.id,text}));});bind('#stop',cancel);bind('#back',()=>nav('home'));}
 function calendarGrid(actual,plans,today){
  calendarMonth??=today.slice(0,7);calendarDate??=today;
  const [year,month]=calendarMonth.split('-').map(Number),length=new Date(Date.UTC(year,month,0)).getUTCDate(),offset=(new Date(Date.UTC(year,month-1,1)).getUTCDay()+6)%7;
  const pending=plans.filter(p=>p.status==='planned'&&p.dueDate===calendarDate);
  return `<section class="soft-panel calendar-panel"><div class="section-head"><h2 id="calendar-month">${calendarMonth} · 学习日历</h2><div class="actions"><button id="month-prev" aria-label="上个月">‹ 上月</button><button id="month-today">回到今天</button><button id="month-next" aria-label="下个月">下月 ›</button></div></div><p class="note">● 实际活动　○ 计划回访。计划不是已学，不会点亮实际活动。</p><div class="calendar-grid" aria-label="${calendarMonth} 学习日历">${['一','二','三','四','五','六','日'].map(d=>`<span class="weekday">周${d}</span>`).join('')}${'<span aria-hidden="true"></span>'.repeat(offset)}${Array.from({length},(_,i)=>{const date=calendarMonth+'-'+String(i+1).padStart(2,'0'),count=actual.filter(e=>e.date===date).length,plansCount=plans.filter(p=>p.status==='planned'&&p.dueDate===date).length;return `<button data-date="${date}" class="calendar-day ${count?'has-activity':''} ${date===today?'is-today':''}" aria-pressed="${calendarDate===date}" aria-label="${date}，实际活动 ${count} 条，计划回访 ${plansCount} 次"><strong>${i+1}</strong>${count?`<small class="actual-dot">● ${count} 条活动</small>`:'<small class="no-activity">无活动</small>'}${plansCount?`<small class="planned-dot">○ ${plansCount} 次计划</small>`:''}</button>`;}).join('')}</div><h3>${calendarDate} · 当天计划回访</h3>${pending.length?pending.map(p=>`<p>${esc(pack(p.packageId).title)} · 回访 ${p.round} · ${p.characters.join(' ')}（仅计划，未计入已学）</p>`).join(''):'<p>当天没有待回访计划。</p>'}</section>`;
 }
 function calendar(){const s=S(),today=Store.dateKey(),actual=s.events.filter(e=>!['parent_known','help'].includes(e.type)),dates=[calendarDate||today];const labels={listened:'听过故事',meaning:'看图理解',observation:'逐字观察',session_end:'本轮结束',reread_listened:'听过主题复读'};
  main.innerHTML=`<h1>真实记录与回访</h1><p>今天 ${today} · 当前设备时区 ${esc(Store.timezone())}。每条新记录保存发生时间、当时本地日期和时区。</p>${calendarGrid(actual,s.plans,today)}<section class="soft-panel"><h2>计划回访</h2><p>计划不是已学。可以推迟或跳过，不会锁住新故事。A 建议在实际观察后约 1–2 日，B 在 A 实际发生后再隔约 3–5 日。</p>${s.plans.filter(p=>p.status==='planned').map(p=>`<article class="plan-row"><strong>${esc(pack(p.packageId).title)} · 回访 ${p.round}</strong><p>${p.characters.join(' ')} · 计划 ${p.dueDate} · 依据实际日期 ${p.basisDate}</p><div class="actions"><button data-review="${p.id}" class="primary">现在回访</button><button data-later="${p.id}">推迟一天</button><button data-skip="${p.id}">跳过这次计划</button></div></article>`).join('')||'<p>还没有待回访计划。仅听故事不会生成认字回访任务。</p>'}</section><section><h2>${calendarDate} · 实际发生的活动</h2>${dates.map(date=>`<details class="date-record" open><summary>${date} · ${actual.filter(e=>e.date===date).length} 条实际记录</summary>${actual.filter(e=>e.date===date).length?'':'<p>当天没有实际活动。计划回访不会算作已学。</p>'}${actual.filter(e=>e.date===date).map(e=>`<p><time>${new Date(e.occurredAt).toLocaleTimeString('zh-CN',{timeZone:e.timezone})}</time> ${labels[e.type]}${e.packageId?' · '+esc(pack(e.packageId).title):''}${e.char?' · '+e.char+'：'+({independent:'本次独立读出',prompted:'提示后读出',uncertain:'还不确定'}[e.status]):''}${e.type==='meaning'?' · '+(e.correct?'本次选对':'本次未选对'):''}${e.type==='session_end'&&e.listenOnly?' · 听过不等于掌握':''}<small> ${esc(e.timezone)}</small></p>`).join('')}</details>`).join('')||'<p>还没有实际学习记录。选择故事不会产生学习记录。</p>'}</section><section class="soft-panel"><h2>原有记录完整保留</h2><p>原课程记录 ${documentState.events.length} 条，原日期仍按旧版 Asia/Shanghai 保留，不重算历史。</p><a class="button" href="/legacy.html#parent/sprout-3">查看原课程日历</a><button id="export">导出当前本机备份</button><p class="note">备份含本机学习记录，请自己妥善保存；不上传服务器。</p></section>`;
  all('[data-date]').forEach(b=>b.onclick=()=>{calendarDate=b.dataset.date;render();});
  const moveMonth=delta=>{const [y,m]=calendarMonth.split('-').map(Number),date=new Date(Date.UTC(y,m-1+delta,1));calendarMonth=date.toISOString().slice(0,7);calendarDate=calendarMonth+'-01';render();};
  bind('#month-prev',()=>moveMonth(-1));bind('#month-next',()=>moveMonth(1));bind('#month-today',()=>{calendarDate=today;calendarMonth=today.slice(0,7);render();});
  all('[data-review]').forEach(b=>b.onclick=async()=>{if(await save({type:'review',planId:b.dataset.review,sessionId:uid()}))nav('learn');});all('[data-later]').forEach(b=>b.onclick=()=>{const p=s.plans.find(p=>p.id===b.dataset.later);save({type:'plan',planId:p.id,dueDate:Store.addDays(p.dueDate<today?today:p.dueDate,1)});});all('[data-skip]').forEach(b=>b.onclick=()=>save({type:'plan',planId:b.dataset.skip,status:'skipped'}));bind('#export',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(documentState,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='小芽本机备份-'+today+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 }
 function recordingsReady(){const clips=globalThis.SproutAudioManifest?.clips||{};const texts=catalog.packages.flatMap(p=>[...p.sentences,...p.recognition.map(r=>r.sentence),SproutStoryArt.question(p.id)]).concat(catalog.rereads.flatMap(r=>r.sentences));return texts.every(t=>Boolean(clips[t.normalize('NFC').trim()]));}
 function roadmap(){const stages=[['第一阶段',300,'35 基础字＋265 新增候选字；53 包故事、选图和逐字观察内容；录音齐备后才能完成听读。'],['第二阶段',800,'新增 500 字，100 包、20 主题；当前仅编排蓝图。'],['第三阶段',1500,'长期容量规划，完整内容尚未制作。'],['第四阶段',2200,'长期容量规划，完整内容尚未制作。'],['第五阶段',3000,'长期家庭目标，完整内容尚未制作。']];main.innerHTML=`<h1>每一程，慢慢长大</h1><p class="note">3000 字是长期家庭目标，不是学前标准，也不是按期掌握保证。候选容量不等于孩子已会。</p><div class="stage-list">${stages.map(([title,n,desc],i)=>`<article><span class="stage-number">${i+1}</span><div><h2>${title} · 累计 ${n} 字</h2><p>${desc}</p><strong>${i===0?(recordingsReady()?'课程已制作 · 自由选故事':'课程测试中 · 录音待补齐'):'规划 · 尚不可学习'}</strong></div></article>`).join('')}</div><h2>第二阶段：蓝图预览</h2><p>以下仅有标题、候选字与情节方向。完整故事、练读句、音频与互动课件尚未制作，因此没有学习按钮。</p>${catalog.stage2.themes.map(t=>`<details><summary>${t.id}. ${esc(t.title)} · 待制作</summary><p>${esc(t.focus)}</p>${catalog.stage2.packages.filter(p=>p.theme===t.title).map(p=>`<article><h3>${p.id}. ${esc(p.title)}</h3><p>${p.characters.join('　')}</p><p>${esc(p.outline)}</p><small>蓝图，尚不可学习</small></article>`).join('')}</details>`).join('')}<button id="back">返回可学故事</button>`;bind('#back',()=>nav('home'));}
 async function boot(){try{[catalog,legacy]=await Promise.all(['/story-course.json','/course.json'].map(u=>fetch(u,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('课程文件读取失败');return r.json();})));documentState=await Store.transaction(null,catalog,legacy);render();message('本机记录已就绪 · 听过不等于学会');}catch(e){message(e.message+'，未清空或覆盖旧记录。',true);main.innerHTML='<h1>小花园暂时打不开</h1><p>请检查资源加载与浏览器存储权限。</p><button id="retry">重新读取</button>';bind('#retry',boot);}}
 window.addEventListener('hashchange',()=>{cancel();render();});window.addEventListener('pagehide',cancel);document.addEventListener('visibilitychange',()=>{if(document.hidden)cancel();});boot();
})();
